1	//! Pollable handles for I/O submitted to pegaflow's runtime.
2	//!
3	//! Every offload operation the scheduler cares about resolves through one
4	//! [`OffloadHandle`]: submit on the engine, then poll at step boundaries —
5	//! never block the serving loop (#799/#802). Dropping a handle detaches the
6	//! observer, not the I/O: the underlying task keeps running (and keeps its
7	//! keep-alive payload) until it settles on its own.
8	
9	use pegaflow_core::EngineError;
10	use pegaflow_core::QueryLeaseId;
11	use tokio::sync::oneshot;
12	
13	/// In-flight handle for one operation submitted to pegaflow's worker.
14	///
15	/// [`Self::poll`] keeps scheduler admission non-blocking; [`Self::wait`]
16	/// blocks for tests and non-pipelined callers.
17	pub struct OffloadHandle<T> {
18	    rx: oneshot::Receiver<Result<T, EngineError>>,
19	}
20	
21	/// CPU→GPU load; resolves when the DMA completes.
22	pub type LoadHandle = OffloadHandle<()>;
23	
24	/// GPU→CPU save; resolves when the host tier has captured the data (the
25	/// source GPU blocks are reusable from that point).
26	pub(crate) type SaveHandle = OffloadHandle<()>;
27	
28	/// Prefix query; resolves to a [`QueryOutcome`] once pegaflow has counted the
29	/// local hit and — for `Loading` outcomes — leaves the background fetch
30	/// running (re-submit with the same `req_id` to poll it).
31	pub(crate) type QueryHandle = OffloadHandle<QueryOutcome>;
32	
33	impl<T> OffloadHandle<T> {
34	    pub(crate) fn from_rx(rx: oneshot::Receiver<Result<T, EngineError>>) -> Self {
35	        Self { rx }
36	    }
37	
38	    /// Non-blocking check for a scheduler tick. `None` while still in flight.
39	    pub fn poll(&mut self) -> Option<Result<T, EngineError>> {
40	        match self.rx.try_recv() {
41	            Ok(result) => Some(result),
42	            Err(oneshot::error::TryRecvError::Empty) => None,
43	            Err(oneshot::error::TryRecvError::Closed) => Some(Err(EngineError::Storage(
44	                "offload worker dropped reply".into(),
45	            ))),
46	        }
47	    }
48	
49	    /// Block the current thread until the operation settles.
50	    pub fn wait(self) -> Result<T, EngineError> {
51	        self.rx
52	            .blocking_recv()
53	            .unwrap_or_else(|_| Err(EngineError::Storage("offload worker dropped reply".into())))
54	    }
55	
56	    /// Await settlement from an async context ([`Self::poll`]/[`Self::wait`]
57	    /// are the duals for the synchronous scheduler thread).
58	    pub async fn settle(self) -> Result<T, EngineError> {
59	        self.rx
60	            .await
61	            .unwrap_or_else(|_| Err(EngineError::Storage("offload worker dropped reply".into())))
62	    }
63	
64	    /// A handle that is already settled with `result` — lets scheduler tests
65	    /// drive their admission poll path without a pegaflow worker.
66	    pub(crate) fn settled(result: Result<T, EngineError>) -> Self {
67	        let (tx, rx) = oneshot::channel();
68	        let _ = tx.send(result);
69	        Self { rx }
70	    }
71	
72	    /// A handle plus the sender that settles it — scheduler tests exercise
73	    /// the parked/in-flight path, then resolve it on their own schedule.
74	    pub fn in_flight() -> (Self, oneshot::Sender<Result<T, EngineError>>) {
75	        let (tx, rx) = oneshot::channel();
76	        (Self { rx }, tx)
77	    }
78	}
79	
80	/// A query hit: how many prefix blocks pegaflow can return from its CPU tier,
81	/// and the lease that owns those blocks until `OffloadEngine::load` consumes
82	/// it. `num_blocks == 0` means a full miss and `lease` is `None`.
83	pub struct QueryHit {
84	    pub lease: Option<QueryLeaseId>,
85	    pub num_blocks: usize,
86	}
87	
88	/// Outcome of an `OffloadEngine` query.
89	pub enum QueryOutcome {
90	    /// Terminal: `hit.num_blocks` prefix blocks are host-resident and leased.
91	    Ready(QueryHit),
92	    /// pegaflow kicked off an async fetch of the missing prefix from a remote
93	    /// peer (P2P) or SSD. Not terminal: re-query with the same `req_id` next
94	    /// tick to poll; the fetch resolves to `Ready` (with the pulled blocks) or
95	    /// falls back to a plain local hit count. Only occurs with a deeper tier
96	    /// configured — never in the host-memory-only setup.
97	    Loading,
98	}
99

